/* Three coordinate scales, linked density/CDF, and finite midpoint quadrature.
   Canvas tails are clipped at -4; the unshown left tail is added to every sum. */
(()=>{'use strict';
const M=NormalMath,PHI0=M.pdf(0),TAIL=M.cdf(-4),clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
const integral='<math aria-label="Φ(z) 等于 Z 小于等于 z 的概率，等于负无穷至 z 的标准正态密度积分"><mi>Φ</mi><mo>(</mo><mi>z</mi><mo>)</mo><mo>=</mo><mi>P</mi><mo>(</mo><mi>Z</mi><mo>≤</mo><mi>z</mi><mo>)</mo><mo>=</mo><msubsup><mo>∫</mo><mrow><mo>−</mo><mi>∞</mi></mrow><mi mathcolor="#b1843d">z</mi></msubsup><mi>φ</mi><mo>(</mo><mi>t</mi><mo>)</mo><mspace width="0.2em"/><mi>d</mi><mi>t</mi></math>';
const sumFormula="<div class=\"normal-sum-row\"><math class=\"normal-sum-formula\" aria-label=\"Φ(z) 近似等于负4以下的左尾概率，加上小矩形面积之和\"><mi>Φ</mi><mo>(</mo><mi>z</mi><mo>)</mo><mo>≈</mo><mi>Φ</mi><mo>(</mo><mo>−</mo><mn>4</mn><mo>)</mo><mo>+</mo><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>m</mi></munderover><mi>φ</mi><mo>(</mo><msub><mi>t</mi><mi>i</mi></msub><mo>)</mo><mi>Δt</mi></math></div>";
function create({canvas,ctx,state,manual,invalidate}){
 const $=id=>document.getElementById(id),u={phase:0,standardRunning:false,n:24,integralRunning:false,progress:1},color={green:'#237e5c',gold:'#b98b42',blue:'#638ba2',muted:'#84988a',grid:'#d8e3d6',ink:'#244d3b'};let visible=-1;
 const value=()=>({x:state.mu+state.sigma*state.z,y:state.sigma*state.z,z:state.z}),area=()=>M.cdf(state.z),quad=()=>M.midpoint(-4,state.z,u.n);
 function pause(){const wasRunning=u.standardRunning||u.integralRunning;u.standardRunning=false;u.integralRunning=false;if(wasRunning)actions()}
 function reset(){pause();Object.assign(u,{phase:0,n:24,progress:1});actions();update()}
 function enter(step,autoplay=false){pause();visible=step;if(step===6){u.phase=0;u.standardRunning=autoplay}if(step===8){u.progress=autoplay?0:1;u.integralRunning=autoplay}actions();update()}
 function actions(){const a=$('normal-actions');a.replaceChildren();const add=(id,label,fn,pressed)=>{const b=document.createElement('button');b.id=id;b.textContent=label;if(pressed!==undefined)b.setAttribute('aria-pressed',String(pressed));b.onclick=()=>{const prior={standard:u.standardRunning,integral:u.integralRunning};manual();fn(prior);actions();update();invalidate()};a.append(b)};
  if(visible===6){['① 原始 X','② 减去 μ','③ 除以 σ'].forEach((v,i)=>add('standard-'+i,v,()=>{u.phase=i},Math.round(u.phase)===i));add('standard-play',u.standardRunning?'暂停步骤':'▶ 逐步演示',prior=>{if(!prior.standard){if(u.phase>=2)u.phase=0;u.standardRunning=true}})}
  if(visible===7){[[-1.96,'−1.96'],[0,'0'],[1.96,'1.96']].forEach(([z,label],i)=>add('cdf-preset-'+i,'z = '+label,()=>state.z=z))}
  if(visible===8){[8,24,64,160].forEach(n=>add('integral-n-'+n,n+' 个矩形',()=>{u.n=n;u.progress=1},u.n===n));add('integral-play',u.integralRunning?'暂停累加':'▶ 逐个累加',prior=>{if(!prior.integral){if(u.progress>=1)u.progress=0;u.integralRunning=true}})}
 }
 function setFormula(key,html){const e=$('normal-formula');if(e.dataset.formula!==key){e.innerHTML=html;e.dataset.formula=key}}
 function update(){const is=state.step>=7;const only=state.step>=7;$('mu').closest('label').hidden=only;$('sigma').closest('label').hidden=only;document.querySelector('.separator').hidden=only;$('standard-identity').hidden=!only;$('normal-extension').hidden=!is;$('z-control').hidden=state.step<6;document.body.classList.toggle('normal-extended',state.step>=4);if(!is)return;
  $('z-bound').value=state.z;$('z-value').textContent=state.z.toFixed(2);const v=value();
  if(visible===6){setFormula('standard','<math aria-label="先减均值，再除标准差，Z 等于 X 减 μ 后除以 σ，服从标准正态分布"><mi>X</mi><mo>∼</mo><mi>N</mi><mo>(</mo><mi>μ</mi><mo>,</mo><msup><mi>σ</mi><mn>2</mn></msup><mo>)</mo><mspace width="1em"/><mo>→</mo><mspace width="1em"/><mi>Z</mi><mo>=</mo><mfrac><mrow><mi>X</mi><mo>−</mo><mi>μ</mi></mrow><mi>σ</mi></mfrac><mo>∼</mo><mi>N</mi><mo>(</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo>)</mo></math>');$('normal-numeric').textContent=`同一个观测：${v.x.toFixed(1)} → ${v.y.toFixed(1)} → ${v.z.toFixed(2)}　｜　P = ${area().toFixed(6)}`;$('normal-note').textContent='三幅图使用不同刻度；横轴换单位，密度高度同步换算，概率面积不变。'}
  else{setFormula(visible===8?'integral':'cdf',integral+(visible===8?sumFormula:''));if(visible===7){$('normal-numeric').textContent=`z = ${state.z.toFixed(2)}　｜　Φ(z) = ${area().toFixed(6)} = ${(area()*100).toFixed(2)}%`;$('normal-note').textContent='左图阴影面积 = 右图点的高度；图示从 −4 起，公式从 −∞ 起。'}else{const q=quad(),k=Math.min(u.n,Math.floor(u.progress*u.n+1e-6)),partial=k?q.rectangles[k-1].sum:0,approx=partial+TAIL;$('normal-numeric').textContent=`已累加 ${k}/${u.n}　｜　矩形和 + 左尾 = ${approx.toFixed(6)}　｜　Φ(z) = ${area().toFixed(6)}`;$('normal-note').textContent='每块面积 = φ(tᵢ)Δt；−4 左侧未画的面积约 0.000032，已补入累积值。'}}
  canvas.dataset.standardPhase=u.phase.toFixed(3);canvas.dataset.integrationCount=String(Math.min(u.n,Math.floor(u.progress*u.n+1e-6)));canvas.dataset.cdf=area().toFixed(7);invalidate();
 }
 function tick(dt){let changed=false;if(visible===6&&u.standardRunning){u.phase=Math.min(2,u.phase+dt/1600);if(u.phase===2){u.standardRunning=false;actions()}changed=true}if(visible===8&&u.integralRunning){u.progress=Math.min(1,u.progress+dt/3600);if(u.progress===1){u.integralRunning=false;actions()}changed=true}if(changed)update();return changed}
 function label(text,x,y,{size=13,c=color.ink,align='center',bold=false}={}){ctx.save();ctx.font=`${bold?500:400} ${size}px "Microsoft YaHei",sans-serif`;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillStyle=c;ctx.fillText(text,x,y);ctx.restore()}
 function stroke(points,c=color.grid,width=1,dash=[]){if(points.length<2)return;ctx.save();ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle=c;ctx.lineWidth=width;ctx.setLineDash(dash);ctx.lineJoin='round';ctx.lineCap='round';ctx.stroke();ctx.restore()}
 function fill(points,c,alpha=.2){ctx.save();ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.globalAlpha=alpha;ctx.fillStyle=c;ctx.fill();ctx.restore()}
 function dot(p,c=color.gold,r=4){ctx.save();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(p.x,p.y,r+2,0,7);ctx.fill();ctx.fillStyle=c;ctx.beginPath();ctx.arc(p.x,p.y,r,0,7);ctx.fill();ctx.restore()}
 function panels(w,h,n){const top=state.step===8?152:116,bottom=88,space=18;if(w<720){const hh=(h-top-bottom-space*(n-1))/n;return Array.from({length:n},(_,i)=>({x:28,y:top+i*(hh+space),w:w-56,h:hh}))}const ww=(w-120-space*(n-1))/n;return Array.from({length:n},(_,i)=>({x:60+i*(ww+space),y:top+12,w:ww,h:h-top-bottom-24}))}
 function plot(rect,camera,{max=.45,title='',sub='',alpha=1,xLabel=v=>v.toFixed(0),ticks=[-4,-2,0,2,4],yTicks=[],unit=''}={}){const pad=rect.w<330?24:35,ww=rect.w-pad*2,hh=Math.max(55,rect.h-110),cx=rect.x+rect.w/2,base=rect.y+rect.h-31,cy=Math.cos(camera.yaw),sy=Math.sin(camera.yaw),cp=Math.cos(camera.pitch),sp=Math.sin(camera.pitch),project=(x,y,z=0)=>{const xx=x/8*ww*camera.zoom,yy=y/max*hh*camera.zoom,zz=-xx*sy+z*cy,k=1/(1+zz/(Math.max(ww,hh)*4)),rx=xx*cy+z*sy,ry=yy*cp-zz*sp;return {x:cx+rx*k,y:base-ry*k}};
  ctx.save();ctx.globalAlpha=alpha;label(title,cx,rect.y+5,{size:15,bold:true});if(sub)label(sub,cx,rect.y+29,{size:11,c:color.muted});const floor=[project(-4,0,-9),project(4,0,-9),project(4,0,9),project(-4,0,9)];fill(floor,'#bed0b9',.24);for(const t of ticks){stroke([project(t,0,-9),project(t,0,9)],color.grid,.7);const p=project(t,0);stroke([p,project(t,-max*.025)],'#94ac95');label(xLabel(t),p.x,p.y+15,{size:11,c:color.muted})}stroke([project(-4,0),project(4,0)],'#8ba38b',1.2);stroke([project(-4,0),project(-4,max)],'#a0b5a0',.9);for(const yt of yTicks){const p=project(-4,yt);label(yt.toFixed(yt<.5?2:1),p.x-8,p.y,{size:10,c:color.muted,align:'right'});stroke([p,project(4,yt)],color.grid,.5,[3,5])}if(unit){const p=project(4,0);label(unit,p.x+10,p.y,{size:11,c:color.muted,align:'left'})}ctx.restore();return {project,rect,alpha}}
 function density(chart,z,{colorLine=color.green,alpha=1}={}){const p=chart.project,line=Array.from({length:241},(_,i)=>{const x=-4+i/30;return p(x,M.pdf(x))}),shade=[p(-4,0)];for(let i=0;i<=160;i++){const x=-4+(z+4)*i/160;shade.push(p(x,M.pdf(x)))}shade.push(p(z,0));ctx.save();ctx.globalAlpha=alpha;fill(shade,colorLine,.25);stroke(line,colorLine,2.7);stroke([p(0,0),p(0,PHI0)],'#8dad92',1,[4,5]);stroke([p(z,0),p(z,M.pdf(z))],color.gold,1.4,[4,4]);dot(p(z,M.pdf(z)),color.gold);ctx.restore()}
 function standard(w,h,camera){const rects=panels(w,h,3),v=value(),phase=Math.floor(u.phase+.0001),vals=[v.x,v.y,v.z],scales=[state.sigma,state.sigma,1],means=[state.mu,0,0],names=['① 原始变量 X','② 中心化 Y=X−μ','③ 标准化 Z=Y/σ'],marks=[];
  rects.forEach((rect,i)=>{const alpha=i>phase?.24:i<phase?.52:1,chart=plot(rect,camera,{max:.46,title:names[i],sub:`均值 ${means[i]} · 标准差 ${scales[i]}`,alpha,xLabel:t=>(means[i]+t*scales[i]).toFixed(0),ticks:[-2,-1,0,1,2],unit:i===2?'z':i===1?'y':'x'});density(chart,state.z,{alpha});const cp=chart.project(state.z,M.pdf(state.z));marks.push(cp);label(`密度峰值 ${(PHI0/scales[i]).toFixed(4)}`,rect.x+rect.w/2,rect.y+49,{size:11,c:color.muted});const foot=chart.project(state.z,0);label(`${i===0?'x':i===1?'y':'z'}=${vals[i].toFixed(i===2?2:1)}`,foot.x,foot.y+34,{size:12,c:i===phase?color.gold:color.muted});const center=chart.project(0,.16);label(`面积 ${area().toFixed(4)}`,center.x,center.y,{size:12,c:color.green});});
  if(u.standardRunning&&u.phase<2){const i=Math.floor(u.phase),f=u.phase-i,a=marks[i],b=marks[i+1],p={x:a.x+(b.x-a.x)*f,y:a.y+(b.y-a.y)*f};stroke([a,b],color.gold,1,[3,5]);dot(p,color.gold,6);label((vals[i]+(vals[i+1]-vals[i])*f).toFixed(2),p.x,p.y-20,{size:14,c:color.gold,bold:true})}
 }
 function linked(w,h,camera,integrating=false){const [a,b]=panels(w,h,2),left=plot(a,camera,{title:integrating?'密度：小矩形累加':'密度 φ(t)',sub:'φ(t) = exp(−t²/2) / √(2π)',max:.46,yTicks:[.2,.4],unit:'t'}),right=plot(b,camera,{title:'累积分布 Φ(z)',sub:'点的高度 = 左侧累积面积',max:1.08,yTicks:[.5,1],unit:'z'}),p=left.project,r=right.project;density(left,state.z);const curve=Array.from({length:241},(_,i)=>{const z=-4+i/30;return r(z,M.cdf(z))});stroke(curve,color.green,2.8);const exact=r(state.z,area());stroke([r(state.z,0),exact,r(-4,area())],color.gold,1.3,[4,4]);dot(exact,color.gold,5);label(area().toFixed(6),exact.x,exact.y-18,{size:12,c:color.gold});const zp=r(state.z,0);label('z='+state.z.toFixed(2),zp.x,zp.y+34,{size:12,c:color.gold});
  if(!integrating){const c=p((state.z-4)/2,.08);label('面积 '+area().toFixed(6),c.x,c.y,{size:13,c:color.green});const at=p(state.z,0);label('z='+state.z.toFixed(2),at.x,at.y+34,{size:12,c:color.gold})}
  else{const q=quad(),k=Math.min(u.n,Math.floor(u.progress*u.n+1e-6)),acc=[r(-4,TAIL)];for(let i=0;i<k;i++){const v=q.rectangles[i],active=i===k-1;fill([p(v.left,0),p(v.left,v.height),p(v.right,v.height),p(v.right,0)],active?color.gold:color.green,active?.5:.16);stroke([p(v.left,0),p(v.left,v.height),p(v.right,v.height),p(v.right,0)],active?color.gold:'#759a79',active?1.3:.55);acc.push(r(v.right,TAIL+v.sum));if(active&&u.n<=24){const anchor=p(v.t,v.height);label('φ(tᵢ)',anchor.x,anchor.y-13,{size:12,c:color.gold});const x1=p(v.left,0),x2=p(v.right,0);stroke([{x:x1.x,y:x1.y+25},{x:x2.x,y:x2.y+25}],color.gold,2);label('Δt',(x1.x+x2.x)/2,Math.max(x1.y,x2.y)+39,{size:12,c:color.gold})}}stroke(acc,color.gold,1.7);const last=acc.at(-1);dot(last,color.gold,4);const approx=TAIL+q.sum,err=Math.abs(approx-area());label(`Δt=${q.width.toFixed(4)} · 误差≈${err.toExponential(1)}`,a.x+a.w/2,w<720?a.y+49:a.y+a.h+20,{size:11,c:color.muted});}
  canvas.dataset.bound=state.z.toFixed(4);canvas.dataset.integralUpperLimit=state.z.toFixed(4);
 }
 function draw({w,h,current}){if(state.step===6)standard(w,h,current);else linked(w,h,current,state.step===8)}
 return {enter,update,draw,tick,pause,reset,actions,get diagnostics(){const q=quad();return {...u,z:state.z,x:value().x,centered:value().y,probability:area(),tail:TAIL,approximation:q.sum+TAIL,width:q.width}}};
}
window.NormalExtension={create};
})();
